#requires -Version 5.1
$ErrorActionPreference='Stop';$repo=(Resolve-Path(Join-Path $PSScriptRoot '..')).Path;$python=Join-Path $repo '.venv\Scripts\python.exe';$status=Join-Path $repo 'outputs\operational_health\forex-factory-shadow-trial.json';$tmp="$status.$([guid]::NewGuid().ToString('N')).tmp";New-Item -ItemType Directory -Force -Path(Split-Path $status)|Out-Null
try{& $python -B (Join-Path $repo 'scripts\record_forex_factory_shadow_trial.py');if($LASTEXITCODE-ne 0){throw 'Recorder failed'};& $python -B (Join-Path $repo 'scripts\associate_news_with_strategy_decisions.py');if($LASTEXITCODE-ne 0){throw 'Diagnostic association failed'};$healthResult=@(& $python -B (Join-Path $repo 'scripts\evaluate_forex_factory_trial_health.py'));if($LASTEXITCODE-ne 0){throw 'Health gate failed'};$health=$healthResult[-1]|ConvertFrom-Json;if($health.state-ne'HEALTHY'-or$health.trading_authority-ne$false){throw 'Health policy rejected'};$latest=Get-Content(Join-Path $repo 'outputs\forex_factory_shadow_trial\latest.json')-Raw|ConvertFrom-Json;if($latest.order_influence_permitted-ne$false-or$latest.trading_authority-ne$false){throw 'Authority policy rejected'};[ordered]@{state='OBSERVING';observed_at=[DateTimeOffset]::UtcNow.ToString('o');snapshot_id=$latest.snapshot_id;trial_days=$latest.trial_days;coverage_percent=$health.coverage_percent;order_influence_permitted=$false;trading_authority=$false}|ConvertTo-Json -Compress|Set-Content $tmp -Encoding UTF8;Move-Item $tmp $status -Force}catch{[ordered]@{state='SOURCE_UNAVAILABLE';observed_at=[DateTimeOffset]::UtcNow.ToString('o');order_influence_permitted=$false;trading_authority=$false}|ConvertTo-Json -Compress|Set-Content $tmp -Encoding UTF8;Move-Item $tmp $status -Force;throw}
